//! The Pi vectors of pi-ai's `Type` (`test/parity/sdk-vectors/pi-ai/Type.json`, generated by `automation/gen/generate-sdk-vectors.mjs`): what TypeBox 1.3.27's own constructors and
//! guards return, as the JSON text (so key order and number text are compared), the hidden members and the guards' booleans. Every case is run.

use crate::{TSchema, TValue, Type};
use serde_json::{Map, Value, json};

/// A resolved argument: JSON, or a schema that a `$call` node returned.
fn resolve(node: &Value) -> Result<TValue, String> {
    match node {
        Value::Array(items) => Ok(TValue::List(items.iter().map(resolve).collect::<Result<_, _>>()?)),
        Value::Object(map) => {
            if let Some(Value::String(name)) = map.get("$call") {
                let args: Vec<TValue> = map["args"].as_array().ok_or("no args")?.iter().map(resolve).collect::<Result<_, _>>()?;
                return call(name, &args);
            }
            Ok(TValue::Object(map.iter().map(|(key, value)| Ok((key.clone(), resolve(value)?))).collect::<Result<_, String>>()?))
        }
        other => Ok(TValue::Json(other.clone())),
    }
}

fn options(args: &[TValue], index: usize) -> Option<Map<String, Value>> {
    match args.get(index) {
        Some(TValue::Object(pairs)) => Some(pairs.iter().map(|(key, value)| (key.clone(), value.to_value())).collect()),
        _ => None,
    }
}

fn schema(value: Result<TSchema, String>) -> Result<TValue, String> {
    value.map(TValue::Schema)
}

fn flag(value: bool) -> Result<TValue, String> {
    Ok(TValue::Json(Value::Bool(value)))
}

fn literal_of(value: &TValue) -> Result<crate::LiteralValue, String> {
    match value {
        TValue::Json(Value::String(text)) => Ok(text.as_str().into()),
        TValue::Json(Value::Bool(flag)) => Ok((*flag).into()),
        TValue::Json(Value::Number(number)) => number.as_f64().map(Into::into).ok_or_else(|| "Invalid Literal value".to_string()),
        _ => Err("Invalid Literal value".to_string()),
    }
}

/// An Object-typed argument as the schema constructors take it: a JSON object of members.
fn pairs(value: &TValue) -> Vec<(String, TValue)> {
    match value {
        TValue::Object(pairs) => pairs.clone(),
        TValue::Json(Value::Object(map)) => map.iter().map(|(key, value)| (key.clone(), TValue::Json(value.clone()))).collect(),
        _ => Vec::new(),
    }
}

/// The spec of a `{"$fn": name, ...}` argument, as the member map of its JSON.
fn spec(value: &TValue) -> Result<Map<String, Value>, String> {
    match value.to_value() {
        Value::Object(map) if map.contains_key("$fn") => Ok(map),
        other => Err(format!("{other} is not a function spec")),
    }
}

fn number(spec: &Map<String, Value>, key: &str) -> f64 {
    spec.get(key).and_then(Value::as_f64).unwrap_or(0.0)
}

/// The predicate a case names (the generator's `predicateFor` builds the same from the same spec).
fn check_of(spec: Map<String, Value>) -> impl Fn(&Value) -> Result<bool, String> + Send + Sync + 'static {
    move |value| {
        let name = spec["$fn"].as_str().unwrap_or("");
        match name {
            "always" => Ok(true),
            "never" => Ok(false),
            "lengthAtLeast" => Ok(value.as_str().map_or(0, |text| text.len()) as f64 >= number(&spec, "n")),
            "equals" => Ok(*value == spec["value"]),
            "even" => Ok(value.as_f64().is_some_and(|n| n % 2.0 == 0.0)),
            "greaterThan" => Ok(value.as_f64().is_some_and(|n| n > number(&spec, "n"))),
            "throws" | "throwsText" => Err(spec["message"].as_str().unwrap_or("").to_string()),
            other => Err(format!("no predicate {other}")),
        }
    }
}

fn message_of(spec: Map<String, Value>) -> Box<dyn Fn(&Value) -> Result<String, String> + Send + Sync> {
    Box::new(move |value| match spec["$fn"].as_str().unwrap_or("") {
        "text" => Ok(spec["text"].as_str().unwrap_or("").to_string()),
        "textWithValue" => Ok(format!("{}{}", spec["prefix"].as_str().unwrap_or(""), value.as_str().map_or_else(|| value.to_string(), str::to_string))),
        "errorThrows" => Err(spec["message"].as_str().unwrap_or("").to_string()),
        other => Err(format!("no message function {other}")),
    })
}

fn call(name: &str, a: &[TValue]) -> Result<TValue, String> {
    let opts = |index: usize| options(a, index);
    let first = || a.first().cloned().unwrap_or(TValue::Json(Value::Null));
    match name {
        "Any" => schema(Ok(Type::any(opts(0).as_ref()))),
        "Unknown" => schema(Ok(Type::unknown(opts(0).as_ref()))),
        "String" => schema(Ok(Type::string(opts(0).as_ref()))),
        "Number" => schema(Ok(Type::number(opts(0).as_ref()))),
        "Integer" => schema(Ok(Type::integer(opts(0).as_ref()))),
        "Boolean" => schema(Ok(Type::boolean(opts(0).as_ref()))),
        "Null" => schema(Ok(Type::null(opts(0).as_ref()))),
        "Never" => schema(Ok(Type::never(opts(0).as_ref()))),
        "Undefined" => schema(Ok(Type::undefined(opts(0).as_ref()))),
        "Void" => schema(Ok(Type::void(opts(0).as_ref()))),
        "Symbol" => schema(Ok(Type::symbol(opts(0).as_ref()))),
        "BigInt" => schema(Ok(Type::big_int(opts(0).as_ref()))),
        "Ref" => schema(Ok(Type::ref_(first().to_value().as_str().ok_or("ref is not a string")?, opts(1).as_ref()))),
        "Array" => schema(Ok(Type::array(first(), opts(1).as_ref()))),
        "Union" => schema(Ok(Type::union(list(&first()), opts(1).as_ref()))),
        "Intersect" => schema(Ok(Type::intersect(list(&first()), opts(1).as_ref()))),
        "Literal" => schema(Type::literal(literal_of(&first())?, opts(1).as_ref())),
        "Enum" => schema(Type::enum_(&first().to_value(), opts(1).as_ref())),
        "Object" => schema(Ok(Type::object(pairs(&first()), opts(1).as_ref()))),
        "Refine" => {
            let message = a.get(2).map(spec).transpose()?.map(message_of);
            schema(Type::refine_value(first(), check_of(spec(&a[1])?), message))
        }
        "IsRefine" => match first() {
            TValue::Schema(schema) => flag(Type::is_refine(&schema)),
            _ => flag(false),
        },
        "Optional" => schema(Type::optional_value(first())),
        "Readonly" => schema(Type::readonly_value(first())),
        "Immutable" => schema(Type::immutable_value(first())),
        "Unsafe" => schema(Type::unsafe_(first())),
        "With" => schema(Type::with(first(), opts(1).as_ref())),
        "Record" => schema(Type::record(first(), a[1].clone(), opts(2).as_ref())),
        "IsKind" => flag(Type::is_kind(first(), a[1].to_value().as_str().ok_or("kind is not a string")?)),
        "IsSchema" => flag(Type::is_schema(first())),
        "IsOptional" => flag(Type::is_optional(first())),
        "IsReadonly" => flag(Type::is_readonly(first())),
        "IsImmutable" => flag(Type::is_immutable(first())),
        "IsUnsafe" => flag(Type::is_unsafe(first())),
        "IsEnumValue" => flag(Type::is_enum_value(&first().to_value())),
        "IsAny" => flag(Type::is_any(first())),
        "IsArray" => flag(Type::is_array(first())),
        "IsBigInt" => flag(Type::is_big_int(first())),
        "IsBoolean" => flag(Type::is_boolean(first())),
        "IsEnum" => flag(Type::is_enum(first())),
        "IsInteger" => flag(Type::is_integer(first())),
        "IsIntersect" => flag(Type::is_intersect(first())),
        "IsLiteral" => flag(Type::is_literal(first())),
        "IsNever" => flag(Type::is_never(first())),
        "IsNull" => flag(Type::is_null(first())),
        "IsNumber" => flag(Type::is_number(first())),
        "IsObject" => flag(Type::is_object(first())),
        "IsRecord" => flag(Type::is_record(first())),
        "IsRef" => flag(Type::is_ref(first())),
        "IsString" => flag(Type::is_string(first())),
        "IsSymbol" => flag(Type::is_symbol(first())),
        "IsUndefined" => flag(Type::is_undefined(first())),
        "IsUnion" => flag(Type::is_union(first())),
        "IsUnknown" => flag(Type::is_unknown(first())),
        "IsVoid" => flag(Type::is_void(first())),
        other => Err(format!("the SDK's Type has no {other}")),
    }
}

fn list(value: &TValue) -> Vec<TValue> {
    match value {
        TValue::List(items) => items.clone(),
        TValue::Json(Value::Array(items)) => items.iter().cloned().map(TValue::Json).collect(),
        _ => Vec::new(),
    }
}

#[test]
fn type_matches_pi() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../test/parity/sdk-vectors/pi-ai/Type.json");
    let file: Value = serde_json::from_slice(&std::fs::read(path).expect("test/parity/sdk-vectors/pi-ai/Type.json")).expect("valid JSON");
    let cases = file["cases"].as_array().expect("cases");
    assert!(!cases.is_empty(), "Type.json has no cases");
    let mut failures = Vec::new();
    for case in cases {
        let name = case["name"].as_str().unwrap_or("?");
        let got = resolve(&case["args"][0]);
        if let Some(throws) = case.get("throws").and_then(Value::as_str) {
            match got {
                Err(message) if message.trim_start_matches("TypeError: ") == throws => {}
                other => failures.push(format!("{name}: {other:?}, Pi throws {throws:?}")),
            }
            continue;
        }
        let want = &case["result"];
        match got {
            Err(message) => failures.push(format!("{name}: {message}, Pi answers {want}")),
            Ok(TValue::Schema(schema)) => {
                let text = schema.to_json();
                if want["json"].as_str() != Some(text.as_str()) {
                    failures.push(format!("{name}:\n got {text}\n Pi  {}", want["json"]));
                }
                let hidden: Map<String, Value> = want["hidden"].as_object().cloned().unwrap_or_default();
                let mut have: Map<String, Value> = schema.hidden_members().iter().map(|(key, value)| (key.clone(), value.clone())).collect();
                if !schema.refinements().is_empty() {
                    // Functions have no JSON form: the vector records how many there are.
                    have.insert("~refine".into(), json!({"count": schema.refinements().len()}));
                }
                if have != hidden {
                    failures.push(format!("{name}: hidden members {have:?}, Pi {hidden:?}"));
                }
            }
            Ok(other) => {
                if other.to_value() != *want {
                    failures.push(format!("{name}: {:?}, Pi {want}", other.to_value()));
                }
            }
        }
    }
    assert!(failures.is_empty(), "{} of {} cases differ from Pi:\n{}", failures.len(), cases.len(), failures.join("\n"));
}
